CREATE TYPE user_role AS ENUM ('PEMOHON','AGEN','ADMIN');
CREATE TYPE ticket_status AS ENUM ('BARU','DIPROSES','MENUNGGU_PEMOHON','SELESAI','DITUTUP','DIBATALKAN');
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE CHECK (email=lower(email)), name text NOT NULL, department text NOT NULL DEFAULT '', role user_role NOT NULL, password_hash text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE teams (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE);
CREATE TABLE memberships (user_id uuid REFERENCES users(id), team_id uuid REFERENCES teams(id), PRIMARY KEY(user_id,team_id));
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user ON sessions(user_id);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE login_attempts (key text PRIMARY KEY, attempts integer NOT NULL, reset_at timestamptz NOT NULL);
CREATE TABLE services (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, description text NOT NULL, kind text NOT NULL CHECK(kind IN ('INCIDENT','REQUEST')), team_id uuid NOT NULL REFERENCES teams(id), active boolean NOT NULL DEFAULT true);
CREATE TABLE target_settings (priority text PRIMARY KEY CHECK(priority IN ('P1','P2','P3','P4')), response_hours integer NOT NULL CHECK(response_hours BETWEEN 1 AND 8760), resolution_hours integer NOT NULL CHECK(resolution_hours BETWEEN 1 AND 8760));
CREATE TABLE priority_settings (impact integer NOT NULL CHECK(impact BETWEEN 1 AND 3), urgency integer NOT NULL CHECK(urgency BETWEEN 1 AND 3), priority text NOT NULL REFERENCES target_settings(priority), PRIMARY KEY(impact,urgency));
CREATE SEQUENCE ticket_number_seq;
CREATE TABLE tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), number text NOT NULL UNIQUE DEFAULT ('IT-' || extract(year FROM now() AT TIME ZONE 'Asia/Jakarta')::text || '-' || lpad(nextval('ticket_number_seq')::text,6,'0')), requester_id uuid NOT NULL REFERENCES users(id), service_id uuid NOT NULL REFERENCES services(id), team_id uuid NOT NULL REFERENCES teams(id), agent_id uuid REFERENCES users(id), kind text NOT NULL CHECK(kind IN ('INCIDENT','REQUEST')), subject text NOT NULL, description text NOT NULL, impact integer NOT NULL CHECK(impact BETWEEN 1 AND 3), urgency integer NOT NULL CHECK(urgency BETWEEN 1 AND 3), priority text NOT NULL REFERENCES target_settings(priority), status ticket_status NOT NULL DEFAULT 'BARU', version integer NOT NULL DEFAULT 1, resolution text, response_due timestamptz NOT NULL, first_response_at timestamptz, resolution_due timestamptz, resolution_remaining_ms bigint NOT NULL, paused_at timestamptz, related_id uuid REFERENCES tickets(id), idempotency_key uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(requester_id,idempotency_key));
CREATE INDEX tickets_requester_queue ON tickets(requester_id,status,created_at DESC);
CREATE INDEX tickets_team_queue ON tickets(team_id,status,created_at DESC);
CREATE INDEX tickets_service_priority ON tickets(service_id,priority,created_at DESC);
CREATE INDEX tickets_assignment ON tickets(agent_id,created_at DESC);
CREATE INDEX tickets_subject_search ON tickets USING gin(to_tsvector('simple',subject || ' ' || description));
CREATE TABLE messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id uuid NOT NULL REFERENCES tickets(id), author_id uuid NOT NULL REFERENCES users(id), body text NOT NULL, internal boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX messages_timeline ON messages(ticket_id,created_at);
CREATE TABLE attachments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id uuid NOT NULL REFERENCES tickets(id), name text NOT NULL, storage_name uuid NOT NULL UNIQUE, mime text NOT NULL CHECK(mime IN ('application/pdf','image/png','image/jpeg','text/plain')), size integer NOT NULL CHECK(size BETWEEN 1 AND 10485760), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX attachments_ticket ON attachments(ticket_id);
CREATE TABLE ticket_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id uuid NOT NULL REFERENCES tickets(id), actor_id uuid NOT NULL REFERENCES users(id), kind text NOT NULL, detail text NOT NULL, internal boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX events_timeline ON ticket_events(ticket_id,created_at);
CREATE FUNCTION deny_event_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Ticket activity is append-only'; END $$;
CREATE TRIGGER append_only_events BEFORE UPDATE OR DELETE ON ticket_events FOR EACH ROW EXECUTE FUNCTION deny_event_mutation();
CREATE TABLE articles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, title text NOT NULL, body text NOT NULL, service_id uuid NOT NULL REFERENCES services(id), published boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), ticket_id uuid NOT NULL REFERENCES tickets(id), body text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX notifications_inbox ON notifications(user_id,created_at DESC);
